<?php require_once __DIR__.'/includes/bootstrap.php';require_login('save this page');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: dashboard.php');exit;}check_csrf();$return=return_url($_POST['return']??'dashboard.php');try{$pdo->exec('CREATE TABLE IF NOT EXISTS saved_items(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,item_type VARCHAR(40) NOT NULL,item_key VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY user_item(user_id,item_type,item_key))');$s=$pdo->prepare('INSERT IGNORE INTO saved_items(user_id,item_type,item_key) VALUES(?,?,?)');$s->execute([(int)$_SESSION['user']['id'],trim($_POST['type']??'page'),trim($_POST['type']??'page')]);}catch(Throwable $e){error_log($e->getMessage());}header('Location: '.$return.'?saved=1');exit;
